var server = createDreamcashServer({
  apiUrl: checkedApiUrl(process.env.DREAMCASH_API_URL ?? "https://api.dreamcash.xyz"),
  keyFile: defaultKeyFile()
});
await server.connect(new StdioServerTransport);
